#include <stdio.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int x[100];
    int H = 0;

    for (int i = 0; i < N; i++) {
        scanf("%d", &x[i]);
        if (x[i] > H) H = x[i];
    }

    for (int row = H - 1; row >= 0; row--) {
        for (int i = 0; i < N; i++) {
            if (i > 0) putchar(' ');
            putchar(x[i] > row ? '1' : '0');
        }
        putchar('\n');
    }

    return 0;
}
